 * Typed Analytics Worker Protocol for DuckDB-Wasm
 */
import { initDuckDbWasm } from '../lib/wasm-loader';

export interface QueryRequest {
  sql: string;
}

export interface QueryResponse<T = any> {
  columns: string[];
  rows: T[][];
  durationMs?: number;
}

/**
 * DuckDB Analytics Worker Module.
 * Handles SQL execution within the WebAssembly context.
 */
class DuckDbAnalyticsWorker {
  private dbInstance: any | null = null;

  async initialize(): Promise<void> {
    // Initialize WASM instance if not already loaded
    this.dbInstance = await initDuckDbWasm();
  }

  /**
   * Execute a SQL query and return typed results.
   */
  executeQuery<T>(request: QueryRequest): Promise<QueryResponse<T>> {
    const startTime = performance.now();

    try {
      if (!this.dbInstance) {
        throw new Error('DuckDB instance not initialized');
      }

      // Execute SQL via DuckDB-Wasm API (pseudo-code for structure)
      const result = this.dbInstance.query(request.sql);

      return {
        columns: Object.keys(result),
        rows: result,
        durationMs: performance.now() - startTime
      };
    } catch (error) {
      throw new Error(`Query failed: ${error}`);
    }
  }
}

// Singleton instance for the worker thread context
let workerInstance: DuckDbAnalyticsWorker | null = null;

export async function getDuckDbWorker(): Promise<DuckDbAnalyticsWorker> {
  if (!workerInstance) {
    const instance = new DuckDbAnalyticsWorker();
    await instance.initialize();
    workerInstance = instance;
  }
  return workerInstance;
}
